[{"order":1,"type":"heading","text":"Spread and Rest Operators in JavaScript"},{"order":2,"type":"paragraph","text":"The spread and rest operators are powerful features introduced in ES6 (ECMAScript 2015) that provide concise ways to work with arrays and objects. They use the same syntax (three dots: ...), but their functionality depends on the context in which they are used."},{"order":3,"type":"subheading","text":"Spread Operator"},{"order":4,"type":"paragraph","text":"The spread operator allows you to expand an iterable (like an array or string) into individual elements. It can be used in several contexts, such as:"},{"order":5,"type":"bullet_point","text":"Creating copies of arrays or objects."},{"order":6,"type":"bullet_point","text":"Combining arrays or objects."},{"order":7,"type":"bullet_point","text":"Passing arguments to functions."},{"order":8,"type":"code","text":"// Copying an array
const arr1 = [1, 2, 3];
const arr2 = [...arr1]; // Creates a new array with the same elements as arr1

console.log(arr2); // Output: [1, 2, 3]
console.log(arr1 === arr2); // Output: false (they are different arrays in memory)"},{"order":9,"type":"code","text":"// Combining arrays
const arr3 = [4, 5, 6];
const combinedArray = [...arr1, ...arr3];

console.log(combinedArray); // Output: [1, 2, 3, 4, 5, 6]"},{"order":10,"type":"code","text":"// Copying an object
const obj1 = { a: 1, b: 2 };
const obj2 = { ...obj1 };

console.log(obj2); // Output: { a: 1, b: 2 }
console.log(obj1 === obj2); // Output: false (different objects in memory)"},{"order":11,"type":"code","text":"// Combining objects
const obj3 = { c: 3, d: 4 };
const combinedObject = { ...obj1, ...obj3 };

console.log(combinedObject); // Output: { a: 1, b: 2, c: 3, d: 4 }"},{"order":12,"type":"code","text":"// Passing arguments to a function
function sum(x, y, z) {
  return x + y + z;
}

const numbers = [1, 2, 3];
console.log(sum(...numbers)); // Output: 6"},{"order":13,"type":"subheading","text":"Rest Operator"},{"order":14,"type":"paragraph","text":"The rest operator allows you to collect multiple elements into an array. It is typically used in function parameters to handle a variable number of arguments."},{"order":15,"type":"code","text":"// Collecting function arguments into an array
function myFunc(a, b, ...args) {
  console.log("a:", a);
  console.log("b:", b);
  console.log("args:", args); // args is an array of the remaining arguments
}

myFunc(1, 2, 3, 4, 5);
// Output:
// a: 1
// b: 2
// args: [3, 4, 5]"},{"order":16,"type":"code","text":"// Rest parameter in destructuring
const [first, second, ...rest] = [10, 20, 30, 40, 50];

console.log(first);   // Output: 10
console.log(second);  // Output: 20
console.log(rest);    // Output: [30, 40, 50]"},{"order":17,"type":"subheading","text":"Key Differences and Considerations"},{"order":18,"type":"paragraph","text":"While the syntax is the same, the spread operator expands elements, while the rest operator collects elements. The spread operator is used when calling functions or creating new arrays/objects, while the rest operator is used in function definitions or destructuring assignments."},{"order":19,"type":"paragraph","text":"It's important to note that the spread operator creates shallow copies. For deeply nested objects or arrays, you might need to use deep copy techniques to avoid unintended side effects."}]
